describe('Faceted Search Results Update Without Full Page Reload', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should update search results when applying a facet filter without full page reload', () => {
    // Verify initial search results are displayed
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Intercept the API call for faceted search update
    cy.intercept('GET', '/api/search/facet/results*').as('updateResults');

    // Click on a facet filter option
    cy.get('[data-testid="facet-filter-category"]').should('be.visible');
    cy.get('[data-testid="facet-option-electronics"]').click();

    // Wait for the API call to complete
    cy.wait('@updateResults');

    // Verify results are updated without page reload
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify the filter is applied
    cy.get('[data-testid="facet-filter-category"]').should('contain', 'Electronics');

    // Verify the URL does not change to a full page reload
    cy.url().should('include', '?facet=category:electronics');
  });

  it('should handle empty search results when applying a facet filter', () => {
    // Intercept the API call for faceted search update
    cy.intercept('GET', '/api/search/facet/results*').as('updateResults');

    // Apply a facet filter that yields no results
    cy.get('[data-testid="facet-filter-color"]').should('be.visible');
    cy.get('[data-testid="facet-option-purple"]').click();

    // Wait for the API call
    cy.wait('@updateResults');

    // Verify empty state message is displayed
    cy.get('[data-testid="empty-results-message"]').should('be.visible');
    cy.get('[data-testid="empty-results-message"]').should('contain', 'No results found');

    // Verify results container is empty
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('not.exist');

    // Verify the filter is still applied
    cy.get('[data-testid="facet-filter-color"]').should('contain', 'Purple');
  });
});
